<?php
declare(strict_types=1);
namespace App\Controllers\Admin;

use App\Middleware\AdminAuthMiddleware;
use App\Services\Admin\AdminAuthorizationService;
use App\Services\Admin\AdminCmsService;
use App\Services\Admin\AdminCmsMediaService;
use App\Services\Admin\AdminSiteSettingsService;
use PDOException;
use RuntimeException;
use Throwable;

final class AdminCmsController
{
    public function __construct(private readonly AdminAuthorizationService $authz=new AdminAuthorizationService()){}
    public function index():void{$this->listing('articles');}
    public function listing(string $kind):void{$admin=$this->authz->requirePermission('cms.view');try{$service=new AdminCmsService();$data=$service->listing($kind,(string)($_GET['status']??''));$data['kind']=$kind;$this->page($admin,ucfirst($kind),'admin/cms/list',$data,'cms');}catch(Throwable $e){$this->failure($e,'CMS list');}}
    public function form(string $kind,string $ref=''):void{$admin=$this->authz->requirePermission('cms.manage');$id=$ref!==''?filter_var($ref,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):false;if($ref!==''&&$id===false){$this->notFound();return;}try{$service=new AdminCmsService();$viewKind=match($kind){'articles'=>'article','pages'=>'page','faqs'=>'faq',default=>throw new RuntimeException('Content type not found.',404)};$item=$id?$service->item($viewKind,(int)$id):null;if($id&&!$item){$this->notFound();return;}$data=['item'=>$item,'kind'=>$viewKind,'categories'=>$kind==='articles'?$service->categories():[],'isEdit'=>(bool)$id];$this->page($admin,($id?'Edit ':'Create ').ucfirst($viewKind),'admin/cms/form',$data,'cms');}catch(Throwable $e){$this->failure($e,'CMS form');}}
    public function save(string $kind,string $ref=''):void{$admin=$this->authz->requirePermission('cms.manage');if(!$this->csrf())return;$id=$ref!==''?filter_var($ref,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]):null;if($ref!==''&&$id===false){$this->notFound();return;}try{$type=match($kind){'articles'=>'article','pages'=>'page','faqs'=>'faq',default=>throw new RuntimeException('Content type not found.',404)};(new AdminCmsService())->save($type,(int)$admin['id'],$_POST,$id?(int)$id:null);$_SESSION['_flash']['admin_info']='Content saved.';\redirect('admin/cms/'.$kind);}catch(Throwable $e){$this->mutationFailure($e,'CMS save','admin/cms/'.$kind);}}
    public function categories():void{$admin=$this->authz->requirePermission('cms.view');try{$this->page($admin,'Article Categories','admin/cms/categories',['categories'=>(new AdminCmsService())->categories()],'cms');}catch(Throwable $e){$this->failure($e,'CMS categories');}}
    public function saveCategory(string $ref=''):void{$admin=$this->authz->requirePermission('cms.manage');if(!$this->csrf())return;$id=$ref===''?null:filter_var($ref,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($ref!==''&&$id===false){$this->notFound();return;}try{(new AdminCmsService())->saveCategory((int)$admin['id'],$_POST,$id?(int)$id:null);$_SESSION['_flash']['admin_info']='Article category saved.';\redirect('admin/cms/categories');}catch(Throwable $e){$this->mutationFailure($e,'CMS category','admin/cms/categories');}}
    public function settings():void{$admin=$this->authz->requirePermission('settings.view');try{$svc=new AdminSiteSettingsService();$fields=$svc->all();$isPreview=(($_GET['preview']??'')==='1');if($isPreview){$_SESSION['cms_preview_settings']=$fields;$_SESSION['cms_preview_expires']=time()+300;$_SESSION['cms_preview_nonce']=bin2hex(random_bytes(24));}$this->page($admin,'Site Settings','admin/settings',['fields'=>$fields,'isPreview'=>$isPreview,'previewUrl'=>$isPreview?\site_url('admin/cms/preview/'.$_SESSION['cms_preview_nonce']):null],'settings');}catch(Throwable $e){$this->failure($e,'site settings');}}
    public function saveSettings():void{$admin=$this->authz->requirePermission('settings.manage');if(!$this->csrf())return;try{(new AdminSiteSettingsService())->save((int)$admin['id'],$_POST);unset($_SESSION['cms_preview_settings'],$_SESSION['cms_preview_nonce'],$_SESSION['cms_preview_expires']);$_SESSION['_flash']['admin_info']='Site settings saved.';\redirect('admin/settings');}catch(Throwable $e){$this->mutationFailure($e,'site settings','admin/settings');}}
    public function upload():void{$admin=$this->authz->requirePermission('cms.manage');if(!$this->csrf())return;try{$path=(new AdminCmsMediaService())->store((int)$admin['id'],$_FILES['media']??[]);$_SESSION['_flash']['admin_info']='Image uploaded. Add descriptive alt text before publishing.';$_SESSION['_flash']['admin_media']=$path;\redirect('admin/cms/media');}catch(Throwable $e){$this->mutationFailure($e,'CMS media upload','admin/cms/media');}}
    public function media():void{$admin=$this->authz->requirePermission('cms.view');$media=$_SESSION['_flash']['admin_media']??null;unset($_SESSION['_flash']['admin_media']);$this->page($admin,'CMS Media','admin/cms/media',['media'=>$media],'cms');}
    public function contacts():void{$admin=$this->authz->requirePermission('cms.view');try{$rows=\App\Database::connection()->query('SELECT id,name,email,phone,subject,message,status,created_at FROM contact_messages ORDER BY FIELD(status,"new","read","replied","closed"),created_at DESC LIMIT 300')->fetchAll();$this->page($admin,'Contact Messages','admin/cms/contacts',['rows'=>$rows,'permissions'=>$this->authz->permissions((int)$admin['id'])],'cms');}catch(Throwable $e){$this->failure($e,'contact inbox');}}
    public function preview(string $nonce):void{$admin=$this->authz->requirePermission('settings.view');if(!isset($_SESSION['cms_preview_nonce'],$_SESSION['cms_preview_expires'])||!hash_equals((string)$_SESSION['cms_preview_nonce'],$nonce)||(int)$_SESSION['cms_preview_expires']<time()){http_response_code(404);\render('admin/error-page',['title'=>'Preview expired','status'=>404,'message'=>'Return to settings and prepare a fresh preview.','loginUrl'=>\admin_url('login')]);return;}AdminAuthMiddleware::headers();$data=$_SESSION['cms_preview_settings']??[];$brand=(string)($data['company_name']['value']??'MultiForex');\render('admin/layout/layout',['title'=>'CMS preview · MultiForex Administration','pageTitle'=>'CMS preview','admin'=>$admin,'permissions'=>$this->authz->permissions((int)$admin['id']),'adminData'=>['companyName'=>$brand,'fields'=>$data],'contentView'=>'public/preview','activeRoute'=>'settings','csrfToken'=>\generate_admin_csrf_token(),'notice'=>null,'error'=>null]);}
    public function contactStatus(string $ref):void{$admin=$this->authz->requirePermission('support.reply');if(!$this->csrf())return;$id=filter_var($ref,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$status=$_POST['status']??'';if($id===false||!in_array($status,['new','read','replied','closed'],true)){$this->notFound();return;}try{$pdo=\App\Database::connection();$pdo->beginTransaction();$q=$pdo->prepare('SELECT status FROM contact_messages WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if($old===false)throw new RuntimeException('Contact message not found.',404);if($old===$status)throw new RuntimeException('No status changes to save.',409);$q=$pdo->prepare('UPDATE contact_messages SET status=?,updated_at=NOW() WHERE id=?');$q->execute([$status,$id]);\App\Services\Admin\AdminActivityLogger::logOrFail((int)$admin['id'],'contact_message_status_updated','contact_message',(int)$id,json_encode(['old_status'=>$old,'new_status'=>$status],JSON_THROW_ON_ERROR));$pdo->commit();$_SESSION['_flash']['admin_info']='Contact message status updated.';\redirect('admin/cms/contacts');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$this->mutationFailure($e,'contact message status','admin/cms/contacts');}}
    private function page(array $admin,string $title,string $view,array $data,string $active):void{AdminAuthMiddleware::headers();$perms=$this->authz->permissions((int)$admin['id']);\render('admin/layout/layout',['title'=>$title.' · MultiForex Administration','pageTitle'=>$title,'admin'=>$admin,'permissions'=>$perms,'adminData'=>$data,'contentView'=>$view,'activeRoute'=>$active,'csrfToken'=>\generate_admin_csrf_token(),'notice'=>\flash_get('admin_info'),'error'=>\flash_get('admin_error')]);}
    private function csrf():bool{if(\verify_admin_csrf_token(is_string($_POST['_admin_csrf']??null)?$_POST['_admin_csrf']:null))return true;AdminAuthMiddleware::headers();http_response_code(403);\render('admin/error-page',['title'=>'Request could not be verified','status'=>403,'message'=>'Refresh the administration page and try again.','loginUrl'=>\admin_url('login')]);return false;}
    private function notFound():void{AdminAuthMiddleware::headers();http_response_code(404);\render('admin/error-page',['title'=>'Not found','status'=>404,'message'=>'The requested CMS item was not found.','loginUrl'=>\admin_url('login')]);}
    private function failure(Throwable $e,string $ctx):void{error_log('Admin '.$ctx.' unavailable: '.get_class($e));AdminAuthMiddleware::headers();http_response_code(503);\render('admin/error-page',['title'=>'Page temporarily unavailable','status'=>503,'message'=>'This administration data could not be loaded. Please try again shortly.','loginUrl'=>\admin_url('login')]);}
    private function mutationFailure(Throwable $e,string $ctx,string $fallback):void{$code=(int)$e->getCode();$status=$e instanceof PDOException?503:($e instanceof RuntimeException?($code===409?409:($code===404?404:422)):500);$_SESSION['_flash']['admin_error']=in_array($status,[409,404,422],true)?$e->getMessage():'This request could not be completed. Please try again shortly.';if($status===503||$status===500)error_log('Admin '.$ctx.' failed: '.get_class($e));\redirect($fallback);}
}
